CREATE PROCEDURE [aportaciones].[spGuardarIndividualesAhorroHistorico_Lote]
(
    @Lotes   [aportaciones].[TVP_AhorroLoteHeader_V2]  READONLY,
    @Detalle [aportaciones].[TVP_AhorroLoteDetalle_V2] READONLY,
    @Modo NVARCHAR(10) = N'REPLACE'
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF (@Modo NOT IN (N'REPLACE', N'UPSERT'))
        THROW 50003, 'Modo inválido. Use REPLACE o UPSERT.', 1;

    /* Validación rápida: detalle debe pertenecer a algún lote */
    IF EXISTS (
        SELECT 1
        FROM @Detalle d
        WHERE NOT EXISTS (
            SELECT 1
            FROM @Lotes l
            WHERE l.clave_organica_0 = d.clave_organica_0
              AND l.clave_organica_1 = d.clave_organica_1
              AND l.quincena = d.quincena
              AND l.anio = d.anio
        )
    )
        THROW 50010, 'Hay filas en @Detalle que no pertenecen a ningún lote en @Lotes.', 1;

    DECLARE @Resultados TABLE (
        clave_organica_0 CHAR(2),
        clave_organica_1 CHAR(2),
        quincena INT,
        anio INT,
        insertados_detalle INT,
        insertado_resumen BIT
    );

    BEGIN TRAN;

    /* Cursor por cada lote */
    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
    SELECT clave_organica_0, clave_organica_1, quincena, anio, usuario_id,
           total_empleados, total_contribucion, total_sueldo_base
    FROM @Lotes;

    DECLARE
        @org0 CHAR(2),
        @org1 CHAR(2),
        @qna INT,
        @anio INT,
        @usuario_id NVARCHAR(50),
        @te_hdr INT,
        @tc_hdr DECIMAL(19,6),
        @tsb_hdr DECIMAL(19,6);

    OPEN cur;
    FETCH NEXT FROM cur INTO @org0, @org1, @qna, @anio, @usuario_id, @te_hdr, @tc_hdr, @tsb_hdr;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        /* checks */
        IF (@qna < 1 OR @qna > 24)
            THROW 50001, 'Quincena inválida (1-24).', 1;
        IF (@anio < 2000 OR @anio > 2100)
            THROW 50002, 'Año inválido (2000-2100).', 1;

        /* REPLACE: borrar snapshot */
        IF (@Modo = N'REPLACE')
        BEGIN
            DELETE FROM [aportaciones].[IndividualesAhorroHistorico]
            WHERE clave_organica_0 = @org0
              AND clave_organica_1 = @org1
              AND quincena = @qna
              AND anio = @anio;

            DELETE FROM [aportaciones].[ResumenHistorico]
            WHERE tipo_endpoint = N'individuales/ahorro'
              AND clave_organica_0 = @org0
              AND clave_organica_1 = @org1
              AND quincena = @qna
              AND anio = @anio;
        END

        /* Insert detalle (UPSERT = sólo faltantes) */
        INSERT INTO [aportaciones].[IndividualesAhorroHistorico]
        (
            clave_organica_0, clave_organica_1, quincena, anio,
            interno, nombre, sueldo, quinquenios, otras_prestaciones,
            sueldo_base, afae, afaa, total, usuario_id
        )
        SELECT
            d.clave_organica_0, d.clave_organica_1, d.quincena, d.anio,
            d.interno, d.nombre, d.sueldo, d.quinquenios, d.otras_prestaciones,
            d.sueldo_base, d.afae, d.afaa, d.total, @usuario_id
        FROM @Detalle d
        WHERE d.clave_organica_0 = @org0
          AND d.clave_organica_1 = @org1
          AND d.quincena = @qna
          AND d.anio = @anio
          AND (
                @Modo = N'REPLACE'
                OR NOT EXISTS (
                    SELECT 1
                    FROM [aportaciones].[IndividualesAhorroHistorico] h
                    WHERE h.clave_organica_0 = @org0
                      AND h.clave_organica_1 = @org1
                      AND h.quincena = @qna
                      AND h.anio = @anio
                      AND h.interno = d.interno
                )
          );

        DECLARE @insertados INT = @@ROWCOUNT;

        /* Calcular resumen del lote si no viene en header */
        DECLARE
            @te_calc INT,
            @tc_calc DECIMAL(19,6),
            @tsb_calc DECIMAL(19,6);

        SELECT
            @te_calc  = COUNT(1),
            @tc_calc  = SUM(ISNULL(d.total,0)),
            @tsb_calc = SUM(ISNULL(d.sueldo_base,0))
        FROM @Detalle d
        WHERE d.clave_organica_0 = @org0
          AND d.clave_organica_1 = @org1
          AND d.quincena = @qna
          AND d.anio = @anio;

        /* Insert resumen
           - REPLACE: ya borramos
           - UPSERT: si ya existe, lo dejamos; si quieres que actualice, te lo cambio a MERGE
        */
        IF NOT EXISTS (
            SELECT 1
            FROM [aportaciones].[ResumenHistorico] r
            WHERE r.tipo_endpoint = N'individuales/ahorro'
              AND r.clave_organica_0 = @org0
              AND r.clave_organica_1 = @org1
              AND r.quincena = @qna
              AND r.anio = @anio
        )
        BEGIN
            INSERT INTO [aportaciones].[ResumenHistorico]
            (
                tipo_endpoint,
                clave_organica_0, clave_organica_1, quincena, anio,
                total_empleados, total_contribucion, total_sueldo_base,
                usuario_id
            )
            VALUES
            (
                N'individuales/ahorro',
                @org0, @org1, @qna, @anio,
                COALESCE(@te_hdr,  @te_calc),
                COALESCE(@tc_hdr,  @tc_calc),
                COALESCE(@tsb_hdr, @tsb_calc),
                @usuario_id
            );

            INSERT INTO @Resultados VALUES (@org0, @org1, @qna, @anio, @insertados, 1);
        END
        ELSE
        BEGIN
            INSERT INTO @Resultados VALUES (@org0, @org1, @qna, @anio, @insertados, 0);
        END

        FETCH NEXT FROM cur INTO @org0, @org1, @qna, @anio, @usuario_id, @te_hdr, @tc_hdr, @tsb_hdr;
    END

    CLOSE cur;
    DEALLOCATE cur;

    COMMIT;

    SELECT *
    FROM @Resultados
    ORDER BY anio, quincena, clave_organica_0, clave_organica_1;
END

