        @te_hdr INT,
        @tc_hdr DECIMAL(19,6),
        @tsb_hdr DECIMAL(19,6);

    OPEN cur;
    FETCH NEXT FROM cur INTO @org0, @org1, @qna, @anio, @usuario_id, @te_hdr, @tc_hdr, @tsb_hdr;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        IF (@qna < 1 OR @qna > 24)
            THROW 50001, 'Quincena inválida (1-24).', 1;
        IF (@anio < 2000 OR @anio > 2100)
            THROW 50002, 'Año inválido (2000-2100).', 1;

        /* Periodo (CHAR4) = QQ + YY  (ej. qna 1 / 2026 => '0126') */
        DECLARE @periodo CHAR(4) =
            CONCAT(RIGHT('00' + CAST(@qna AS VARCHAR(2)), 2), RIGHT(CAST(@anio AS VARCHAR(4)), 2));

        /* REPLACE: borrar snapshot */
        IF (@Modo = N'REPLACE')
        BEGIN
            DELETE FROM [aportaciones].[IndividualesCairHistorico]
            WHERE clave_organica_0 = @org0
              AND clave_organica_1 = @org1
              AND quincena = @qna
              AND anio = @anio;

            DELETE FROM [aportaciones].[ResumenHistorico]
            WHERE tipo_endpoint = N'individuales/cair'
              AND clave_organica_0 = @org0
              AND clave_organica_1 = @org1
              AND quincena = @qna
              AND anio = @anio;
        END

        /* Insert detalle (UPSERT = sólo faltantes) */
        INSERT INTO [aportaciones].[IndividualesCairHistorico]
        (
            clave_organica_0, clave_organica_1, quincena, anio, periodo,
            interno, nombre, sueldo, quinquenios, otras_prestaciones,
            sueldo_base, afe, total, usuario_id
        )
        SELECT
            d.clave_organica_0, d.clave_organica_1, d.quincena, d.anio, @periodo,
            d.interno, d.nombre, d.sueldo, d.quinquenios, d.otras_prestaciones,
            d.sueldo_base, d.afe, d.total, @usuario_id
        FROM @Detalle d
        WHERE d.clave_organica_0 = @org0
          AND d.clave_organica_1 = @org1
          AND d.quincena = @qna
          AND d.anio = @anio
          AND (
                @Modo = N'REPLACE'
                OR NOT EXISTS (
                    SELECT 1
                    FROM [aportaciones].[IndividualesCairHistorico] h
                    WHERE h.clave_organica_0 = @org0
                      AND h.clave_organica_1 = @org1
                      AND h.quincena = @qna
                      AND h.anio = @anio
                      AND h.interno = d.interno
                )
          );

        DECLARE @insertados INT = @@ROWCOUNT;

        /* Resumen calculado desde detalle (si header viene null) */
        DECLARE
            @te_calc INT,
            @tc_calc DECIMAL(19,6),
            @tsb_calc DECIMAL(19,6);

        SELECT
            @te_calc  = COUNT(1),
            @tc_calc  = SUM(ISNULL(d.total,0)),
            @tsb_calc = SUM(ISNULL(d.sueldo_base,0))
        FROM @Detalle d
        WHERE d.clave_organica_0 = @org0
          AND d.clave_organica_1 = @org1
          AND d.quincena = @qna
          AND d.anio = @anio;

        /* Insert resumen (mismo criterio que tu ejemplo: UPSERT no actualiza si existe) */
        IF NOT EXISTS (
            SELECT 1
            FROM [aportaciones].[ResumenHistorico] r
            WHERE r.tipo_endpoint = N'individuales/cair'
              AND r.clave_organica_0 = @org0
              AND r.clave_organica_1 = @org1
              AND r.quincena = @qna
              AND r.anio = @anio
        )
        BEGIN
            INSERT INTO [aportaciones].[ResumenHistorico]
            (
                tipo_endpoint,
                clave_organica_0, clave_organica_1, quincena, anio,
                total_empleados, total_contribucion, total_sueldo_base,
                usuario_id
            )
            VALUES
            (
                N'individuales/cair',
                @org0, @org1, @qna, @anio,
                COALESCE(@te_hdr,  @te_calc),
                COALESCE(@tc_hdr,  @tc_calc),
                COALESCE(@tsb_hdr, @tsb_calc),
                @usuario_id
            );

            INSERT INTO @Resultados VALUES (@org0, @org1, @qna, @anio, @insertados, 1);
        END
        ELSE
        BEGIN
            INSERT INTO @Resultados VALUES (@org0, @org1, @qna, @anio, @insertados, 0);
        END

        FETCH NEXT FROM cur INTO @org0, @org1, @qna, @anio, @usuario_id, @te_hdr, @tc_hdr, @tsb_hdr;
    END

    CLOSE cur;
    DEALLOCATE cur;

    COMMIT;

    SELECT *
    FROM @Resultados
    ORDER BY anio, quincena, clave_organica_0, clave_organica_1;
END

